// Generated by vibelang from src/details/configured-lsp.vibe; the migrate flow writes it again with each batch.
import * as Predicate from "effect/Predicate";
export function configuredLsps(entries) {
    return entries
        .reduce((names, entry) => {
        if (entry.type !== "document" || entry.info.lsp === undefined)
            return names;
        const lsp = entry.info.lsp;
        if (Predicate.isBoolean(lsp))
            return [];
        return [
            ...names.filter((name) => !Object.hasOwn(lsp, name)),
            ...Object.entries(lsp)
                .filter(([, server]) => !server.disabled)
                .map(([name]) => name),
        ];
    }, [])
        .toSorted((a, b) => a.localeCompare(b));
}
